const mongoose = require('mongoose');

/**
 * Invite Model
 *
 * Tracks each unique share link generated by an inviter for an event.
 *
 * clicks  = number of times someone OPENED the invite link (view count)
 * friendsAttending is NOT stored here — it is calculated on-demand from
 * the RSVP collection by counting RSVPs where:
 *   - shareToken === this invite's inviteCode
 *   - userId !== inviterId  (inviter doesn't count as their own friend)
 */
const inviteSchema = new mongoose.Schema({
  eventId: {
    type: String,
    required: true,
  },
  inviterId: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true,
  },
  // Unique random token used in the share URL
  inviteCode: {
    type: String,
    required: true,
    unique: true,
  },
  // Number of times the invite link was OPENED (not number of RSVPs)
  clicks: {
    type: Number,
    default: 0,
  },
  createdAt: {
    type: Date,
    default: Date.now,
  },
});

module.exports = mongoose.model('Invite', inviteSchema);
